html:
{%- set tasks = frappe.get_all("Task",
        filters={"project": doc.name},
        fields=["name", "subject", "is_group", "exp_start_date", "exp_end_date",
                "duration", "progress", "status", "description", "lft"],
        order_by="lft asc", limit_page_length=0) -%}

{%- macro usdate(v) -%}
{%- if v -%}{%- set s = v|string -%}{{ s[5:7] }}/{{ s[8:10] }}/{{ s[2:4] }}{%- endif -%}
{%- endmacro -%}

{%- set job = doc.project_name.split(" ")[0] -%}

<style>
  .ms { font-family: Arial, "Liberation Sans", "DejaVu Sans", Helvetica, sans-serif; color: #000; font-size: 8pt; }
  .ms-frame { border: 2px solid #000; padding: 12px 6px 7px; }

  /* Logo and the title block share one line, centred against each other -
     the logo is 24px, the title stack about 45px, so flex-end pushed the logo
     to the bottom and made them look unrelated. */
  .ms-head { display: table; width: 100%; margin-bottom: 9px; }
  .ms-head .lg { display: table-cell; vertical-align: middle; text-align: left; }
  .ms-head .ms-title { display: table-cell; vertical-align: middle; }
  .ms-head img { display: block; height: 26px; margin: 0; }
  .ms-title { text-align: right; line-height: 1.15; }
  .ms-title .t1 { font-size: 15pt; font-weight: bold; }
  .ms-title .t2 { font-size: 8.5pt; font-weight: bold; letter-spacing: .05em; }
  .ms-title .t3 { font-size: 7pt; font-weight: bold; }

  table.msT { width: 100%; border-collapse: collapse; border: 2px solid #000;
              table-layout: fixed; }
  table.msT th, table.msT td { border: 1px solid #333; overflow: hidden; }
  table.msT th { font-size: 7pt; text-align: center; font-weight: bold;
                 white-space: nowrap; padding: 2px 4px; }
  table.msT col.cn  { width: 4.5%; }
  table.msT col.ct  { width: 33%; }
  table.msT col.cd  { width: 9.5%; }
  table.msT col.cdy { width: 6%; }
  table.msT col.cst { width: 7.5%; }
  table.msT col.crm { width: 30%; }
  table.msT td.n  { text-align: center; color: #333; font-size: 7pt; padding: 2px 3px; }
  /* generous side padding so the dates never touch the cell rules */
  table.msT td.d  { text-align: center; font-size: 7pt; padding: 2px 6px; }
  table.msT td.dy, table.msT td.st { text-align: center; font-size: 7.5pt; padding: 2px 4px; }
  table.msT td.task { padding: 2px 6px 2px 8px; font-size: 6.5pt; white-space: nowrap; }
  table.msT td.rm   { padding: 2px 6px; font-size: 6pt; white-space: nowrap; }
  table.msT tr.grp td { font-weight: bold; letter-spacing: .26em; font-size: 8pt;
                        white-space: nowrap; padding: 3px 6px; }
  .hp { font-weight: bold; }

  .ms-notes { margin-top: 7px; border: 2px solid #000; padding: 4px 8px; }
  .ms-notes .h { font-weight: bold; letter-spacing: .26em; font-size: 8pt; margin-bottom: 2px; }
  .ms-notes ol { margin: 0; padding-left: 15px; }
  .ms-notes li { font-size: 7pt; margin-bottom: 1px; }

  .ms-foot { margin-top: 7px; border-top: 2px solid #000; padding-top: 4px; font-size: 7pt; }
  .ms-foot .mark { text-align: center; margin-top: 4px; }
  .ms-foot .mark img { height: 18px; display: inline-block; }
  .ms-foot .url { text-align: center; font-weight: bold; font-size: 7pt; margin-top: 1px; }
</style>

<div class="ms"><div class="ms-frame">

  <div class="ms-head">
    <div class="lg"><img src="/assets/mercury/images/mercury_logo.png" alt="Mercury"></div>
    <div class="ms-title">
      <div class="t1">PROJECT SCHEDULE</div>
      <div class="t2">VACUUM PUMP SYSTEM</div>
      <div class="t3">Document: 103-{{ job }}</div>
    </div>
  </div>

  <table class="msT">
    <colgroup>
      <col class="cn"><col class="ct"><col class="cd"><col class="cd">
      <col class="cdy"><col class="cst"><col class="crm">
    </colgroup>
    <thead>
      <tr>
        <th></th><th>Project Task</th><th>Start</th><th>Finish</th>
        <th>Days</th><th>Status</th><th>Remarks</th>
      </tr>
    </thead>
    <tbody>
      {%- set ns = namespace(row=0) -%}
      {%- for t in tasks -%}
      {%- set ns.row = ns.row + 1 -%}
      {%- if t.is_group -%}
        <tr class="grp"><td class="n">{{ ns.row }}</td><td colspan="6">{{ t.subject }}</td></tr>
      {%- else -%}
        {%- set rem = (t.description or "")|striptags|trim -%}
        <tr>
          <td class="n">{{ ns.row }}</td>
          <td class="task">{{ t.subject }}</td>
          <td class="d">{{ usdate(t.exp_start_date) }}</td>
          <td class="d">{{ usdate(t.exp_end_date) }}</td>
          <td class="dy">{{ t.duration or "" }}</td>
          <td class="st">{{ (t.progress or 0)|round(0)|int }}%</td>
          <td class="rm {% if 'Hold Point' in rem %}hp{% endif %}">{{ rem }}</td>
        </tr>
      {%- endif -%}
      {%- endfor -%}
    </tbody>
  </table>

  <div class="ms-notes">
    <div class="h">GENERAL NOTES</div>
    <ol>
      <li>Ship date shown is predicated on Mercury being released to manufacture by the RTM date shown above.</li>
      <li>Customer notification for WP inspections to be 7 days prior to scheduled event.</li>
      <li>Project schedule is subject to change upon receipt of customer comments which have impact design and/or scope of supply.</li>
      <li>Reference Mercury's Inspection &amp; Test Plan, latest approved revision, for fabrication hold points and other Quality requirements.</li>
    </ol>
  </div>

  <div class="ms-foot">
    {{ doc.notes or "" }}
    <div class="mark"><img src="/assets/mercury/images/mercury_mark.png" alt=""></div>
    <div class="url">www.mercuryvacuum.com</div>
  </div>

</div></div>

{%- set proj = frappe.get_doc("Project", doc.project) -%}
{%- set so = frappe.get_all("Sales Order", filters={"project": doc.project},
        fields=["po_no"], limit_page_length=1) -%}
{%- set pono = so and so[0].po_no or "" -%}

{#- doc.date is a STRING in print context, so .strftime() does not exist. -#}
{%- set months = ["January","February","March","April","May","June",
                  "July","August","September","October","November","December"] -%}
{%- set ds = doc.date|string -%}
{%- set nicedate = months[ds[5:7]|int - 1] ~ " " ~ (ds[8:10]|int) ~ ", " ~ ds[0:4] if doc.date else "" -%}

<style>
  .pr { font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 9.5pt; line-height: 1.45; }
  .pr-top { text-align: right; border-bottom: 2px solid #1f4e79; padding-bottom: 7px; }
  .pr-top img { display: inline-block; height: 40px; margin: 0 0 1px; }
  .pr-top .tag { font-size: 8pt; font-style: italic; color: #1f4e79; margin-bottom: 2px; }
  .pr-top .rule { border-top: 3px solid #1f4e79; width: 235px; margin: 2px 0 3px auto; }
  .pr-top .addr { font-size: 7.5pt; color: #1f4e79; line-height: 1.35; }

  .pr-band { display: table; width: 100%; table-layout: fixed; border-collapse: collapse; margin: 18px 0 20px; }
  .pr-band .left { display: table-cell; vertical-align: middle; background: #1f4e79; color: #fff; padding: 26px 22px; width: 45%; }
  .pr-band .left .t1 { font-size: 26pt; line-height: 1.05; }
  .pr-band .left .t2 { font-size: 10pt; margin-top: 3px; }
  .pr-band .right { display: table-cell; vertical-align: middle; width: 55%; border: 1px solid #d0d0d0; border-left: none; padding: 18px 20px; }
  .pr-band table { width: 100%; border-collapse: collapse; font-size: 10pt; }
  .pr-band td { padding: 5px 0; vertical-align: top; border: none; }
  .pr-band td.k { width: 30%; font-weight: bold; }
  .pr-band td.v { font-weight: bold; color: #1f4e79; }

  .pr h3 { font-size: 9.5pt; font-weight: bold; margin: 15px 0 3px; }
  .pr ol { margin: 0; padding-left: 20px; }
  .pr ol li { margin-bottom: 3px; }
  .pr p { margin: 0 0 4px; }
  .pr .attn { margin-bottom: 14px; }
  .pr .sign { margin-top: 24px; }
  .pr .sign .name { font-weight: bold; }
  .pr .att { margin-top: 24px; }
  .pr .att .h { font-weight: bold; }
  .pr-foot { margin-top: 28px; border-top: 1px solid #1f4e79; padding-top: 6px; text-align: center; }
  .pr-foot img { height: 20px; display: inline-block; }
  .pr-foot .url { font-weight: bold; font-size: 7.5pt; color: #1f4e79; margin-top: 2px; }
  .pr-foot .t { font-style: italic; font-size: 7.5pt; color: #444; }

  /* Text Editor fields come back wrapped in Quill markup - <div class="ql-editor">
     plus <span class="ql-ui"> bullets - and .ql-editor carries the EDITOR's font,
     size and padding. That is why a field edited in the UI rendered in a different
     typeface from the rest of the letter. Neutralise it so any future edit inherits. */
  .pr .ql-editor { font-family: inherit; font-size: inherit; line-height: inherit;
                   padding: 0; margin: 0; }
  .pr .ql-ui { display: none; }
  .pr .ql-editor ol, .pr .ql-editor ul { margin: 0; padding-left: 20px; }
  .pr .ql-editor li { margin-bottom: 3px; }
  /* pasted inline font declarations lose to the letter's own type */
  .pr [style*="font-family"], .pr [style*="font-size"] {
     font-family: inherit !important; font-size: inherit !important; }
</style>

<div class="pr">

  <div class="pr-top">
    <img src="/assets/mercury/images/mercury_logo.png" alt="Mercury"><br>
    <div class="tag">Precision engineered.</div>
    <div class="rule"></div>
    <div class="addr">
      <b>Mercury Vacuum Technologies</b><br>
      2001 US Route 46 | Suite 310<br>
      Parsippany, NJ 07054 USA<br>
      (+1) 973.402.4880<br>
      www.mercuryvacuum.com
    </div>
  </div>

  <div class="pr-band">
    <div class="left">
      <div class="t1">Progress Report</div>
      <div class="t2">Vacuum Pump Work in Progress Update</div>
    </div>
    <div class="right">
      <table>
        <tr><td class="k">Project:</td>  <td class="v">{{ proj.project_name.split("(")[-1].replace(")", "").replace("TVA ", "") if "(" in proj.project_name else proj.project_name }}</td></tr>
        <tr><td class="k">Customer:</td> <td class="v">{{ (proj.customer or "").replace(" Inc.", "") }}</td></tr>
        <tr><td class="k">PO#:</td>      <td class="v">{{ pono }}</td></tr>
        <tr><td class="k">Date:</td>     <td class="v">{{ nicedate }}</td></tr>
        <tr><td class="k">Document:</td> <td class="v">{{ doc.custom_document_no or "" }}</td></tr>
      </table>
    </div>
  </div>

  {%- if doc.custom_attention %}
  <div class="attn">Attention:<br>{{ doc.custom_attention|replace("\n", "<br>") }}</div>
  {%- endif %}

  {%- set sections = [
        ("A.", "ENGINEERING & SUBMITTALS", doc.custom_sec_a),
        ("B.", "PROCUREMENT", doc.custom_sec_b),
        ("C.", "METAL FABRICATION", doc.custom_sec_c),
        ("D.", "SYSTEM ASSEMBLY & TESTING", doc.custom_sec_d),
        ("E.", "SCHEDULE & UPCOMING MILESTONES", doc.custom_sec_e),
        ("F.", "PENDING ISSUES", doc.custom_sec_f) ] -%}
  {%- for letter, title, body in sections %}
    <h3>{{ letter }}&nbsp;&nbsp;{{ title }}</h3>
    {{ body or "" }}
  {%- endfor %}

  <div class="sign">
    Any questions or concerns regarding the points discussed above, please do not hesitate to contact us.
    <br><br>Respectfully submitted,<br><br><br>
    <span class="name">{{ doc.custom_signed_by or "" }}</span><br>
    Mercury Vacuum Technologies<br>
    {{ doc.custom_signed_email or "" }}
  </div>

  {%- if doc.custom_attachments %}
  <div class="att">
    <div class="h">ATTACHMENTS:</div>
    {{ doc.custom_attachments|replace("\n", "<br>") }}
  </div>
  {%- endif %}

  <div class="pr-foot">
    <img src="/assets/mercury/images/mercury_mark.png" alt="">
    <div class="url">www.mercuryvacuum.com</div>
    <div class="t">Setting the standard of measure in vacuum performance.</div>
  </div>

</div>
